-- Extraction provenance. Generated by drizzle-kit, then extended by hand: the
-- project_id add is split into add-nullable, backfill, set-not-null, because a
-- NOT NULL column with no default fails against a table that has rows and
-- "nothing writes that table yet" is a claim about this repository rather than
-- about someone's database.
--
-- Nothing here calls a model either. Every column below is bookkeeping the
-- pipeline in phase 1c produces and cannot reconstruct afterwards, which is the
-- only reason it lands before the pipeline does: an atom whose origin was never
-- recorded has no origin to recover, and a candidate that was dropped was never
-- written down to count later.
ALTER TABLE "atoms" ADD COLUMN "extractor_version" text;--> statement-breakpoint
ALTER TABLE "section_extractions" ADD COLUMN "project_id" uuid;--> statement-breakpoint
UPDATE "section_extractions" AS "e"
   SET "project_id" = "d"."project_id"
  FROM "document_sections" AS "s"
  JOIN "documents" AS "d" ON "d"."id" = "s"."document_id"
 WHERE "s"."id" = "e"."section_id"
   AND "e"."project_id" IS NULL;--> statement-breakpoint
ALTER TABLE "section_extractions" ALTER COLUMN "project_id" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "section_extractions" ADD COLUMN "candidates_total" integer;--> statement-breakpoint
ALTER TABLE "section_extractions" ADD COLUMN "candidates_dropped" integer;--> statement-breakpoint
ALTER TABLE "section_extractions" ADD COLUMN "candidates_truncated" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "section_extractions" ADD COLUMN "attempts" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "section_extractions" ADD COLUMN "lease_expires_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "section_extractions" ADD CONSTRAINT "section_extractions_project_id_projects_id_fk" FOREIGN KEY ("project_id") REFERENCES "public"."projects"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "section_extractions_project_id_idx" ON "section_extractions" USING btree ("project_id");--> statement-breakpoint
ALTER TABLE "section_extractions" ADD CONSTRAINT "section_extractions_lease_iff_running" CHECK ((status = 'running') OR (lease_expires_at IS NULL));--> statement-breakpoint
ALTER TABLE "section_extractions" ADD CONSTRAINT "section_extractions_candidates_coherent" CHECK ((candidates_total IS NULL) = (candidates_dropped IS NULL)
          AND (candidates_dropped IS NULL OR candidates_dropped <= candidates_total));
